package got.world.genlayer; public class GOTGenLayerRiver extends GOTGenLayer {public static final int NO_RIVER=-1,RIVER=1;public GOTGenLayerRiver(long s,GOTGenLayer p){super(s);gotParent=p;}private int f(int v){return v>=2?2+(v&1):v;}public int[] getInts(int x,int z,int w,int h){int[] p=gotParent.getInts(x-1,z-1,w+2,h+2),o=new int[w*h];for(int dz=0;dz<h;dz++)for(int dx=0;dx<w;dx++){int c=f(p[dx+1+(dz+1)*(w+2)]);o[dx+dz*w]=(c==f(p[dx+(dz+1)*(w+2)])&&c==f(p[dx+2+(dz+1)*(w+2)])&&c==f(p[dx+1+dz*(w+2)])&&c==f(p[dx+1+(dz+2)*(w+2)]))?NO_RIVER:RIVER;}return o;}}